const PHRASE = ["describe","mask","expose","excite","screen","income","need","badge","dance","sock","option","phone"];
const NAMES = ["Tomas Adeyemi","Priya Nair","Dad","Ellen Okoro","Bank box, Halifax"];
const NOTES = ["fireproof box, Leeds","in the safe at her practice","the tin in the loft","her filing cabinet at home","deposit box 214, opened 2019"];
localStorage.removeItem('keyfob.v1');
const right = Content.QUIZ.map(q => q.a.filter(a => a.ok)[0].t);
App.startBuild('new'); await sleep(160);
document.querySelector('#fGo').click(); await sleep(160);
let ins = [...document.querySelectorAll('#gridHost .wg-in')];
ins.forEach((el, i) => { el.value = PHRASE[i]; });
ins[0].dispatchEvent(new Event('input', { bubbles: true })); await sleep(220);
document.querySelector('#fGo').click(); await sleep(180);
document.querySelector('#fGo').click(); await sleep(180);
for (let i = 0; i < 5; i++) {
  const a = document.querySelector('#pn' + i), b = document.querySelector('#pw' + i);
  a.value = NAMES[i]; a.dispatchEvent(new Event('input', { bubbles: true }));
  b.value = NOTES[i]; b.dispatchEvent(new Event('input', { bubbles: true }));
}
await sleep(180);
document.querySelector('#fGo').click(); await sleep(260);
for (let p = 0; p < 4; p++) {
  const opts = [...document.querySelectorAll('#buildBody .opt:not([disabled])')]
    .filter(o => right.indexOf(o.textContent.trim()) >= 0);
  if (!opts.length) break;
  opts[0].click(); await sleep(200);
}
document.querySelector('#fGo').click(); await sleep(420);
const cards = [];
for (let i = 0; i < 5; i++) {
  if (document.querySelector('#cardReveal')) { document.querySelector('#cardReveal').click(); await sleep(110); }
  cards.push([...document.querySelectorAll('.card-words b span')].map(b => b.textContent));
  if (i < 4) { document.querySelector('#cardNext').click(); await sleep(170); }
}
sessionStorage.setItem('shotCards', JSON.stringify(cards));
for (let i = 0; i < 4; i++) { document.querySelector('#cardPrev').click(); await sleep(150); }
if (document.querySelector('#cardReveal')) { document.querySelector('#cardReveal').click(); await sleep(160); }
document.querySelector('#v-cards .scroller').scrollTop = 0;

})()

